CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text UNIQUE NOT NULL,password_hash text NOT NULL,email_verified boolean NOT NULL DEFAULT false,status text NOT NULL DEFAULT 'active' CHECK(status IN('active','suspended','deleted')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS profiles(user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,full_name text NOT NULL,display_name text,phone text,avatar_url text,language text NOT NULL DEFAULT 'en',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS roles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text UNIQUE NOT NULL,description text);
CREATE TABLE IF NOT EXISTS permissions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code text UNIQUE NOT NULL,description text);
CREATE TABLE IF NOT EXISTS role_permissions(role_id uuid REFERENCES roles(id) ON DELETE CASCADE,permission_id uuid REFERENCES permissions(id) ON DELETE CASCADE,PRIMARY KEY(role_id,permission_id));
CREATE TABLE IF NOT EXISTS departments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text UNIQUE NOT NULL,short_name text,description text,official_email text,website text,building text,room text,phone text,status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','verified','rejected','archived')),created_by uuid REFERENCES users(id),verified_by uuid REFERENCES users(id),verified_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS student_profiles(user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,student_id text,normalized_roll_number text UNIQUE,department_id uuid REFERENCES departments(id),programme text,semester int,admission_year int,graduation_year int,candidate_type text NOT NULL DEFAULT 'cusat_student' CHECK(candidate_type IN('cusat_student','external_candidate','guest_candidate')),verification_status text NOT NULL DEFAULT 'pending' CHECK(verification_status IN('pending','verified','rejected')));
CREATE TABLE IF NOT EXISTS user_roles(user_id uuid REFERENCES users(id) ON DELETE CASCADE,role_id uuid REFERENCES roles(id) ON DELETE CASCADE,department_id uuid REFERENCES departments(id) ON DELETE CASCADE,module text,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,role_id,department_id,module));
CREATE TABLE IF NOT EXISTS department_coordinators(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),department_id uuid REFERENCES departments(id) ON DELETE CASCADE,user_id uuid REFERENCES users(id) ON DELETE CASCADE,designation text,official_email text,verified boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(department_id,user_id));
CREATE TABLE IF NOT EXISTS notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid REFERENCES users(id) ON DELETE CASCADE,type text NOT NULL,title text NOT NULL,message text NOT NULL,link text,read_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor_user_id uuid REFERENCES users(id),action text NOT NULL,entity_type text NOT NULL,entity_id uuid,before_data jsonb,after_data jsonb,created_at timestamptz NOT NULL DEFAULT now());

CREATE TABLE IF NOT EXISTS exams(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),department_id uuid REFERENCES departments(id),coordinator_id uuid NOT NULL REFERENCES users(id),title text NOT NULL,description text,instructions text,registration_open_at timestamptz,registration_close_at timestamptz,starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,duration_minutes int NOT NULL CHECK(duration_minutes>0),attempts_allowed int NOT NULL DEFAULT 1 CHECK(attempts_allowed>0),negative_marking_enabled boolean NOT NULL DEFAULT false,negative_marking_value numeric(8,3) NOT NULL DEFAULT 0,access_type text NOT NULL DEFAULT 'public' CHECK(access_type IN('public','invite','code')),access_code text,status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','review','scheduled','registration_open','live','closed','evaluation','results_ready','archived','cancelled')),published_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(ends_at>starts_at));
CREATE TABLE IF NOT EXISTS question_banks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_user_id uuid NOT NULL REFERENCES users(id),department_id uuid REFERENCES departments(id),title text NOT NULL,description text,source_type text NOT NULL CHECK(source_type IN('pdf','csv','xlsx','json','manual')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS questions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),question_bank_id uuid NOT NULL REFERENCES question_banks(id) ON DELETE CASCADE,question_type text NOT NULL DEFAULT 'single_choice',question_text text NOT NULL,marks numeric(8,3) NOT NULL DEFAULT 1,negative_marks numeric(8,3) NOT NULL DEFAULT 0,difficulty text,metadata jsonb NOT NULL DEFAULT '{}'::jsonb,position int NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(question_bank_id,position));
CREATE TABLE IF NOT EXISTS question_options(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),question_id uuid NOT NULL REFERENCES questions(id) ON DELETE CASCADE,option_key text NOT NULL,option_text text NOT NULL,position int NOT NULL,UNIQUE(question_id,option_key));
CREATE TABLE IF NOT EXISTS exam_questions(exam_id uuid REFERENCES exams(id) ON DELETE CASCADE,question_id uuid REFERENCES questions(id),position int NOT NULL,PRIMARY KEY(exam_id,question_id),UNIQUE(exam_id,position));
CREATE TABLE IF NOT EXISTS answer_key_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),exam_id uuid REFERENCES exams(id) ON DELETE CASCADE,version int NOT NULL,status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','locked','superseded')),created_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),locked_at timestamptz,UNIQUE(exam_id,version));
CREATE TABLE IF NOT EXISTS answer_key_entries(answer_key_version_id uuid REFERENCES answer_key_versions(id) ON DELETE CASCADE,question_id uuid REFERENCES questions(id),correct_option text NOT NULL,marks numeric(8,3) NOT NULL,negative_marks numeric(8,3) NOT NULL DEFAULT 0,PRIMARY KEY(answer_key_version_id,question_id));
CREATE TABLE IF NOT EXISTS exam_registrations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),exam_id uuid REFERENCES exams(id) ON DELETE CASCADE,user_id uuid REFERENCES users(id) ON DELETE SET NULL,candidate_name text NOT NULL,candidate_identifier text,registered_at timestamptz NOT NULL DEFAULT now(),status text NOT NULL DEFAULT 'registered' CHECK(status IN('registered','cancelled','disqualified')),UNIQUE(exam_id,user_id));
CREATE TABLE IF NOT EXISTS exam_attempts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),exam_id uuid REFERENCES exams(id),registration_id uuid REFERENCES exam_registrations(id),user_id uuid REFERENCES users(id) ON DELETE SET NULL,attempt_number int NOT NULL,started_at timestamptz NOT NULL,expires_at timestamptz NOT NULL,submitted_at timestamptz,status text NOT NULL DEFAULT 'active' CHECK(status IN('active','submitted','expired','invalidated')),answer_key_version_id uuid REFERENCES answer_key_versions(id),score numeric(10,3),correct_count int,wrong_count int,skipped_count int,time_taken_seconds int,UNIQUE(exam_id,registration_id,attempt_number));
CREATE TABLE IF NOT EXISTS attempt_answers(attempt_id uuid REFERENCES exam_attempts(id) ON DELETE CASCADE,question_id uuid REFERENCES questions(id),selected_option text,is_marked_for_review boolean NOT NULL DEFAULT false,answered_at timestamptz,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(attempt_id,question_id));
CREATE TABLE IF NOT EXISTS exam_results(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),attempt_id uuid UNIQUE REFERENCES exam_attempts(id) ON DELETE CASCADE,exam_id uuid REFERENCES exams(id),user_id uuid REFERENCES users(id) ON DELETE SET NULL,score numeric(10,3) NOT NULL,total_marks numeric(10,3) NOT NULL,correct_count int NOT NULL,wrong_count int NOT NULL,skipped_count int NOT NULL,time_taken_seconds int,released_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());

CREATE TABLE IF NOT EXISTS resources(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),title text NOT NULL,description text,department_id uuid REFERENCES departments(id),programme text,semester int,category text NOT NULL,source_url text,status text NOT NULL DEFAULT 'pending' CHECK(status IN('draft','pending','approved','rejected','archived')),created_by uuid REFERENCES users(id),approved_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS opportunities(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),title text NOT NULL,organization text NOT NULL,description text,category text NOT NULL,eligibility text,location text,mode text,deadline timestamptz,application_url text,source_url text,status text NOT NULL DEFAULT 'pending' CHECK(status IN('draft','pending','approved','rejected','expired','archived')),created_by uuid REFERENCES users(id),approved_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());

CREATE TABLE IF NOT EXISTS blood_donors(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid UNIQUE REFERENCES users(id) ON DELETE CASCADE,blood_group text NOT NULL,district text,availability_status text NOT NULL DEFAULT 'available',last_donation_date date,consent_status boolean NOT NULL DEFAULT false,verified boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS blood_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),created_by uuid REFERENCES users(id),patient_name text NOT NULL,blood_group text NOT NULL,hospital text NOT NULL,location text,urgency text NOT NULL DEFAULT 'normal' CHECK(urgency IN('normal','urgent','critical')),units_required int NOT NULL DEFAULT 1,needed_at timestamptz,contact_method text,status text NOT NULL DEFAULT 'open' CHECK(status IN('open','matched','fulfilled','cancelled','expired')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS donor_responses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),request_id uuid REFERENCES blood_requests(id) ON DELETE CASCADE,donor_id uuid REFERENCES blood_donors(id),status text NOT NULL DEFAULT 'offered' CHECK(status IN('offered','accepted','declined','withdrawn')),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(request_id,donor_id));
CREATE TABLE IF NOT EXISTS blood_matches(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),request_id uuid REFERENCES blood_requests(id),donor_id uuid REFERENCES blood_donors(id),coordinator_id uuid REFERENCES users(id),status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','confirmed','completed','cancelled')),created_at timestamptz NOT NULL DEFAULT now());

CREATE TABLE IF NOT EXISTS scribe_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),requester_id uuid REFERENCES users(id),event_name text,exam_date date NOT NULL,start_time time,location text,requirements text,status text NOT NULL DEFAULT 'open' CHECK(status IN('open','matching','assigned','completed','cancelled')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS scribe_volunteers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid UNIQUE REFERENCES users(id),languages text[] NOT NULL DEFAULT '{}',availability text,experience text,verification_status text NOT NULL DEFAULT 'pending');
CREATE TABLE IF NOT EXISTS scribe_assignments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),request_id uuid REFERENCES scribe_requests(id),volunteer_id uuid REFERENCES scribe_volunteers(id),coordinator_id uuid REFERENCES users(id),status text NOT NULL DEFAULT 'offered' CHECK(status IN('offered','accepted','declined','completed','cancelled')),assigned_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz);

CREATE TABLE IF NOT EXISTS events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),title text NOT NULL,description text,category text,starts_at timestamptz,ends_at timestamptz,venue text,registration_open boolean NOT NULL DEFAULT false,status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','published','cancelled','completed')),created_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS event_registrations(event_id uuid REFERENCES events(id) ON DELETE CASCADE,user_id uuid REFERENCES users(id) ON DELETE CASCADE,registered_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(event_id,user_id));
CREATE TABLE IF NOT EXISTS competitions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),event_id uuid REFERENCES events(id) ON DELETE SET NULL,title text NOT NULL,description text,deadline timestamptz,status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','open','closed','judging','results_published')),created_by uuid REFERENCES users(id));
CREATE TABLE IF NOT EXISTS competition_entries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),competition_id uuid REFERENCES competitions(id) ON DELETE CASCADE,user_id uuid REFERENCES users(id),submission_url text,submission_text text,score numeric(10,3),status text NOT NULL DEFAULT 'submitted',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS samskara_volunteers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid REFERENCES users(id),area text,application_text text,status text NOT NULL DEFAULT 'pending');

CREATE TABLE IF NOT EXISTS helpdesk_tickets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),created_by uuid REFERENCES users(id),category text NOT NULL,subcategory text,title text NOT NULL,description text NOT NULL,priority text NOT NULL DEFAULT 'normal' CHECK(priority IN('low','normal','high','critical')),status text NOT NULL DEFAULT 'open' CHECK(status IN('open','acknowledged','assigned','in_progress','needs_information','resolved','closed')),assigned_to uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),resolved_at timestamptz);
CREATE TABLE IF NOT EXISTS ticket_messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),ticket_id uuid REFERENCES helpdesk_tickets(id) ON DELETE CASCADE,sender_id uuid REFERENCES users(id),message text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());

CREATE INDEX IF NOT EXISTS idx_exams_start ON exams(starts_at);
CREATE INDEX IF NOT EXISTS idx_attempts_active_expiry ON exam_attempts(expires_at) WHERE status='active';
CREATE INDEX IF NOT EXISTS idx_notifications_user ON notifications(user_id,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_tickets_status ON helpdesk_tickets(status,priority);
CREATE INDEX IF NOT EXISTS idx_opportunities_deadline ON opportunities(status,deadline);
